/**
 * DisplayWindow.js
 * ────────────────
 * Full-screen recognition display designed for a SECOND MONITOR.
 *
 * How it works
 * ────────────
 * • Opened at  http://localhost:3000/?mode=display
 * • Listens on a BroadcastChannel for messages from the main window.
 * • Shows a large, animated recognition card.
 * • Idle state: pulsing scanner animation + live clock.
 * • Known person: green glow, name, greeting, confidence.
 * • Unknown person: red glow, warning animation.
 *
 * Message protocol (from App.js)
 * ──────────────────────────────
 *   { type: 'result', payload: { name, message, confidence, detected, box } }
 *   { type: 'clear' }
 */

import React, { useState, useEffect, useRef } from 'react';

const API_URL = 'http://localhost:5000';

// How long a result card stays visible before returning to idle (ms)
const RESULT_TIMEOUT = 8_000;

// ── PersonAvatar ──────────────────────────────────────────────────────────────
// Shows the person's first dataset image; falls back to their initial letter
// if the image 404s or fails to load for any reason.
function PersonAvatar({ name }) {
  const [imgFailed, setImgFailed] = useState(false);
  const src = `${API_URL}/person-image/${encodeURIComponent(name)}`;

  if (imgFailed) {
    return <>{name.charAt(0).toUpperCase()}</>;
  }

  return (
    <img
      src={src}
      alt={name}
      onError={() => setImgFailed(true)}
      style={{
        width: '100%',
        height: '100%',
        objectFit: 'cover',
        borderRadius: 'inherit',
      }}
    />
  );
}

export default function DisplayWindow({ channelName }) {
  const [result,   setResult]   = useState(null);   // current recognition result
  const [time,     setTime]     = useState('');      // live clock
  const [date,     setDate]     = useState('');      // live date
  const [scanLine, setScanLine] = useState(0);       // animated scanner y-position
  const [show,     setShow]     = useState(false);   // card entrance animation flag

  const clearTimerRef = useRef(null);
  const channelRef    = useRef(null);

  // ── Clock ──────────────────────────────────────────────────────────────
  useEffect(() => {
    const tick = () => {
      const now = new Date();
      setTime(now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }));
      setDate(now.toLocaleDateString([], { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }));
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  // ── Scanner animation (idle state) ───────────────────────────────────
  useEffect(() => {
    let pos = 0;
    const id = setInterval(() => {
      pos = (pos + 1) % 100;
      setScanLine(pos);
    }, 20);
    return () => clearInterval(id);
  }, []);

  // ── BroadcastChannel ─────────────────────────────────────────────────
  useEffect(() => {
    channelRef.current = new BroadcastChannel(channelName);

    channelRef.current.onmessage = (event) => {
      const { type, payload } = event.data;

      if (type === 'result' && payload?.detected) {
        clearTimeout(clearTimerRef.current);
        setShow(false);
        // Brief pause so the entrance animation re-fires on every new result
        setTimeout(() => {
          setResult(payload);
          setShow(true);
        }, 50);

        // Auto-clear after RESULT_TIMEOUT
        clearTimerRef.current = setTimeout(() => {
          setShow(false);
          setTimeout(() => setResult(null), 400);   // wait for exit animation
        }, RESULT_TIMEOUT);
      }

      if (type === 'clear') {
        clearTimeout(clearTimerRef.current);
        setShow(false);
        setTimeout(() => setResult(null), 400);
      }
    };

    return () => {
      channelRef.current?.close();
      clearTimeout(clearTimerRef.current);
    };
  }, [channelName]);

  // ── Helpers ───────────────────────────────────────────────────────────
  const isKnown      = result && result.name !== 'Unknown';
  const confidence   = Math.round((result?.confidence ?? 0) * 100);
  const barBlocks    = Math.round(confidence / 10);

  // ── Render ────────────────────────────────────────────────────────────
  return (
    <div className="dw-root">

      {/* ── Background grid ── */}
      <div className="dw-grid" />

      {/* ── Scan-line (idle state only) ── */}
      {!result && (
        <div
          className="dw-scan-line"
          style={{ top: `${scanLine}%` }}
        />
      )}

      {/* ── Header bar ── */}
      <div className="dw-header">
        <div className="dw-header-left">
          <span className="dw-brand-icon">🎭</span>
          <span className="dw-brand-name">FACE RECOGNITION SYSTEM</span>
        </div>
        <div className="dw-clock">
          <div className="dw-time">{time}</div>
          <div className="dw-date">{date}</div>
        </div>
      </div>

      {/* ── Main content ── */}
      <div className="dw-body">

        {/* ── IDLE state ── */}
        {!result && (
          <div className="dw-idle">
            <div className="dw-idle-ring">
              <div className="dw-idle-inner">
                <span className="dw-idle-icon">👁</span>
              </div>
            </div>
            <p className="dw-idle-text">SCANNING</p>
            <p className="dw-idle-sub">Waiting for face detection…</p>
            <div className="dw-idle-dots">
              <span /><span /><span />
            </div>
          </div>
        )}

        {/* ── RESULT state ── */}
        {result && (
          <div className={`dw-result ${show ? 'dw-result-enter' : 'dw-result-exit'} ${isKnown ? 'dw-known' : 'dw-unknown'}`}>

            {/* Glow orb */}
            <div className={`dw-glow-orb ${isKnown ? 'glow-green' : 'glow-red'}`} />

            {/* Avatar / icon */}
            <div className={`dw-avatar ${isKnown ? 'avatar-known' : 'avatar-unknown'}`}>
              {isKnown
                ? <PersonAvatar name={result.name} />
                : '?'}
            </div>

            {/* Status badge */}
            <div className={`dw-status-badge ${isKnown ? 'badge-known' : 'badge-unknown'}`}>
              {isKnown ? '✅  IDENTITY CONFIRMED' : '⚠️  UNKNOWN PERSON'}
            </div>

            {/* Name */}
            <div className="dw-name">{result.name}</div>

            {/* Custom message */}
            <div className={`dw-message ${isKnown ? 'msg-known' : 'msg-unknown'}`}>
              {result.message}
            </div>

            {/* Confidence bar (only for known) */}
            {isKnown && (
              <div className="dw-confidence">
                <span className="dw-conf-label">CONFIDENCE</span>
                <div className="dw-conf-bar-outer">
                  <div
                    className="dw-conf-bar-inner"
                    style={{ width: `${confidence}%` }}
                  />
                </div>
                <span className="dw-conf-pct">{confidence}%</span>
              </div>
            )}

            {/* Block-style visual bar */}
            {isKnown && (
              <div className="dw-blocks">
                {'█'.repeat(barBlocks)}
                <span className="dw-blocks-empty">{'█'.repeat(10 - barBlocks)}</span>
              </div>
            )}

            {/* Corner brackets decoration */}
            <div className="dw-bracket dw-bracket-tl" />
            <div className="dw-bracket dw-bracket-tr" />
            <div className="dw-bracket dw-bracket-bl" />
            <div className="dw-bracket dw-bracket-br" />

          </div>
        )}
      </div>

      {/* ── Footer ── */}
      <div className="dw-footer">
        <span>POWERED BY FACENET + MTCNN</span>
        <span className={`dw-live ${result ? 'dw-live-active' : ''}`}>
          <span className="dw-live-dot" /> LIVE
        </span>
      </div>

    </div>
  );
}
